save(290,dict(paragraphs=["Sangram Jena writes poetry in Odia and English and works as a translator and literary editor. Contributor notes in The Antonym and Borderless identify his editorial work with Nishant in Odia and Marg Asia in English. His English collection Poems of Passion was published by Sarup and Sons in 2008.","In ‘There I Live’, the village first takes shape through rain, cattle dust, paddy fields and kash flowers. The scene gradually becomes an inward geography: familiar places hold separation, unspoken wishes and the longing for another person's touch. Its movement from a visible landscape into isolation gives the poem its quiet tension."],books=[dict(title='Poems of Passion',detail='English poetry · Sarup and Sons, 2008',url='https://vedamsbooks.com/books/poems_of_passion')],sources=[source('The Antonym — poems and contributor note, 12 November 2021','https://www.theantonymmag.com/poems-by-sangram-jena/','Bilingual writing and journal editorship; author note distinct from translator Bibhu Padhi note.','search_index; direct open failed'),source('Borderless — Sangram Jena’s poetry, 14 July 2025','https://borderlessjournal.com/2025/07/14/found-in-translation-sangram-jenas-poetry/','English/Odia writing and Nishant/Marg Asia editorship.','search_index'),source('Vedams Books — Poems of Passion','https://vedamsbooks.com/books/poems_of_passion','Author, publisher,2008,ISBN9788176258289.','search_index; direct open failed')],identity_match='Captured heading spells Sangarm, biography says Sangram; exact Nishant editorship and English/Odia writing match outside notes. Preserve source heading spelling.',poems_read=[dict(id=302,title='There I Live',coverage='Complete original',basis='Village sensory detail turns toward isolation, wishes and distance from touch.')],limitations=['Captured Sangarm spelling unchanged; Sangram used in new narrative as supplied biography and sources. No present book totals asserted; source totals differ by date. Award not added without successful organiser verification.'],search_queries=['Sangram Jena poet Nishant books','Sangram Jena site:sahitya-akademi.gov.in translation award'],research_leads=[dict(url='https://www.sahitya-akademi.gov.in/awards/anuvad_samman_suchi.jsp',access='search_index; direct find failed',finding='Award list located but author entry not verified; no award claim imported.')],next_action='Author/editor review and confirmation of heading spelling.'))
